"""HSLU look for notebook plots. Palette and style sheet are generated by the hslu-charts skill (no hand-typed colours)."""
from __future__ import annotations

from importlib.resources import files

from .hslu_palette import HSLU, SERIES

STYLE = str(files("claims_lab") / "hslu.mplstyle")
ACCENT = SERIES[0]
GREY = HSLU["neutral"]["grau"]



def show(fig) -> None:
    """Show a figure, then close it, so repeated runs do not keep every figure in memory."""
    import matplotlib.pyplot as plt
    plt.show()
    plt.close(fig)

def use_hslu_style() -> None:
    import matplotlib.pyplot as plt
    plt.style.use(STYLE)


def plot_history(df, reference=None) -> None:
    """Every scoreboard run as one point: cost per claim against decision accuracy. Runs with unsafe approvals are
    marked in magenta, with their number; the latest run has a black outline. `reference` (our recorded runs) are drawn
    as hollow squares."""
    import matplotlib.pyplot as plt
    use_hslu_style()
    unsafe_colour = HSLU["accents"]["magenta"]["base"]
    fig, ax = plt.subplots(figsize=(9, 4.6))
    key = []
    if reference is not None:
        for j, (_, r) in enumerate(reference.iterrows()):
            bad = r["unsafe_approvals"] > 0
            tag = "abcdefgh"[j]
            ax.scatter(r["cost_usd_per_pkg"], r["accuracy"], s=110, marker="s", facecolor="white", zorder=2,
                       edgecolor=unsafe_colour if bad else "#555555", linewidth=1.5)
            ax.annotate(tag, (r["cost_usd_per_pkg"], r["accuracy"]), xytext=(-4, -16), textcoords="offset points",
                        fontsize=9, color="#555555")
            key.append(f"{tag} = {r['label']}" + (f" (unsafe: {int(r['unsafe_approvals'])})" if bad else ""))
        ax.text(1.0, 0.02, "Our recorded runs:\n" + "\n".join(key), transform=ax.transAxes, ha="right", va="bottom",
                fontsize=8, color="#555555")
    if df is not None:
        for i, r in df.reset_index(drop=True).iterrows():
            bad = r["unsafe_approvals"] > 0
            ax.scatter(r["cost_usd_per_pkg"], r["accuracy"], s=140, color=unsafe_colour if bad else ACCENT, zorder=3,
                       edgecolor="black", linewidth=1.5 if i == len(df) - 1 else 0.3)
            note = f"{i + 1}. {r['label']}" + (f" (unsafe: {int(r['unsafe_approvals'])})" if bad else "")
            ax.annotate(note, (r["cost_usd_per_pkg"], r["accuracy"]), xytext=(8, 4), textcoords="offset points", fontsize=9)
    ax.set_xlabel("Cost per claim (USD)")
    ax.set_ylabel("Decision accuracy")
    ax.set_ylim(0, 1.08)
    ax.set_xlim(left=0)
    title = "Each design: accuracy against cost (magenta: paid claims it should not have)"
    ax.set_title(title + ("\nfilled: your runs today · hollow squares: our recorded runs" if reference is not None else ""))
    ax.spines[["top", "right"]].set_visible(False)
    plt.tight_layout()
    show(plt.gcf())


def plot_tokens(calls: list[tuple[int, int]]) -> None:
    """Input and output tokens of each model call in one run: the input grows because every call re-sends the history."""
    import matplotlib.pyplot as plt
    use_hslu_style()
    xs = range(1, len(calls) + 1)
    fig, ax = plt.subplots(figsize=(7, 3))
    ax.bar(xs, [c[0] for c in calls], color=ACCENT, label="input tokens (re-sent history)")
    ax.bar(xs, [c[1] for c in calls], bottom=[c[0] for c in calls], color=GREY, label="output tokens")
    ax.set_xticks(list(xs))
    ax.set_xlabel("Model call in this run")
    ax.set_ylabel("Tokens")
    ax.set_title("Each call re-sends everything before it")
    ax.legend(frameon=False, fontsize=9)
    ax.spines[["top", "right"]].set_visible(False)
    plt.tight_layout()
    show(plt.gcf())


def plot_context(parts: dict) -> None:
    """What filled the last request, as one stacked bar."""
    import matplotlib.pyplot as plt
    use_hslu_style()
    colours = [ACCENT, HSLU["accents"]["magenta"]["base"], GREY, "#9ec9d6", "#555555"]
    total = sum(parts.values()) or 1
    fig, ax = plt.subplots(figsize=(9, 1.6))
    left = 0
    for (name, n), c in zip(parts.items(), colours):
        ax.barh(0, n, left=left, color=c, label=f"{name} ({n / total:.0%})")
        left += n
    ax.set_yticks([])
    ax.set_xlabel("Estimated tokens in the last request")
    ax.legend(frameon=False, fontsize=8, ncol=3, loc="upper center", bbox_to_anchor=(0.5, -0.6))
    ax.spines[["top", "right", "left"]].set_visible(False)
    plt.tight_layout()
    show(plt.gcf())


def plot_contexts(contexts: dict[str, dict]) -> None:
    """What filled the last request of each agent, one stacked bar per agent (the parts of plot_context)."""
    import matplotlib.pyplot as plt
    use_hslu_style()
    colours = [ACCENT, HSLU["accents"]["magenta"]["base"], GREY, "#9ec9d6", "#555555"]
    names = list(contexts)
    fig, ax = plt.subplots(figsize=(9, 0.55 * len(names) + 1.4))
    for row, name in enumerate(names):
        left = 0
        for j, ((part, n), c) in enumerate(zip(contexts[name].items(), colours)):
            ax.barh(row, n, left=left, color=c, label=part if row == 0 else None)
            left += n
        ax.text(left, row, f"  {left:,}", va="center", fontsize=8)
    ax.set_yticks(range(len(names)), names)
    ax.invert_yaxis()
    ax.set_xlabel("Estimated tokens in the agent's last request")
    ax.legend(frameon=False, fontsize=8, ncol=3, loc="upper center", bbox_to_anchor=(0.5, -0.25))
    ax.spines[["top", "right"]].set_visible(False)
    plt.tight_layout()
    show(plt.gcf())


def plot_graph(nodes: list[str], edges: list[tuple[str, str, bool]], fills: dict, thick: set) -> None:
    """A simple local drawing of a LangGraph graph (used when the mermaid.ink service is not reachable): nodes in
    columns by their distance from the start, conditional edges dashed."""
    import matplotlib.pyplot as plt
    use_hslu_style()
    depth = {n: 0 for n in nodes}
    for _ in nodes:  # longest path from __start__, good enough for small acyclic graphs
        for a, b, _c in edges:
            if a != b and depth[b] < depth[a] + 1 <= len(nodes):
                depth[b] = depth[a] + 1
    cols: dict[int, list[str]] = {}
    for n in nodes:
        cols.setdefault(depth[n], []).append(n)
    pos = {n: (d * 2.6, -(i - (len(ns) - 1) / 2) * 1.1) for d, ns in cols.items() for i, n in enumerate(ns)}
    fig, ax = plt.subplots(figsize=(2.3 * len(cols) + 1, 1.0 * max(len(v) for v in cols.values()) + 1.2))
    for a, b, conditional in edges:
        (x1, y1), (x2, y2) = pos[a], pos[b]
        ax.annotate("", (x2 - 0.9, y2), (x1 + 0.9, y1), arrowprops={"arrowstyle": "-|>", "lw": 1,
                    "linestyle": "--" if conditional else "-", "color": "black"})
    for n, (x, y) in pos.items():
        label = n.strip("_")
        ax.text(x, y, label, ha="center", va="center", fontsize=9,
                bbox={"boxstyle": "round,pad=0.4", "facecolor": fills.get(n, "white"), "edgecolor": "black",
                      "linewidth": 3 if n in thick else 1})
    xs = [p[0] for p in pos.values()]
    ys = [p[1] for p in pos.values()]
    ax.set_xlim(min(xs) - 1.2, max(xs) + 1.2)
    ax.set_ylim(min(ys) - 0.8, max(ys) + 0.8)
    ax.axis("off")
    plt.tight_layout()
    show(plt.gcf())


def plot_claims_grid(runs: dict) -> None:
    """Designs by claims: each cell is correct (accent), wrong (grey), an unsafe approval (magenta) or failed (white)."""
    import matplotlib.pyplot as plt
    from matplotlib.colors import ListedColormap
    use_hslu_style()
    labels = list(runs)
    claims = sorted({p for df in runs.values() for p in df["package"]})
    code = {"correct": 0, "wrong": 1, "unsafe": 2, "failed": 3, "": 3}
    grid = []
    for lab in labels:
        df = runs[lab].set_index("package")
        row = []
        for c in claims:
            if c not in df.index:
                row.append(3)
                continue
            r = df.loc[c]
            row.append(3 if r["error"] is not None and r["error"] == r["error"] else 2 if r["unsafe_approval"] else 0 if r["correct"] else 1)
        grid.append(row)
    cmap = ListedColormap([ACCENT, GREY, HSLU["accents"]["magenta"]["base"], "#FFFFFF"])
    fig, ax = plt.subplots(figsize=(0.55 * len(claims) + 3, 0.45 * len(labels) + 1.2))
    ax.imshow(grid, cmap=cmap, vmin=0, vmax=3, aspect="auto")
    ax.set_xticks(range(len(claims)), [c.replace("PKG-", "") for c in claims], rotation=90, fontsize=8)
    ax.set_yticks(range(len(labels)), labels, fontsize=9)
    ax.set_xticks([x - 0.5 for x in range(1, len(claims))], minor=True)
    ax.set_yticks([y - 0.5 for y in range(1, len(labels))], minor=True)
    ax.grid(which="minor", color="white", linewidth=2)
    ax.grid(which="major", visible=False)
    ax.set_title("Per claim: correct (blue), wrong (grey), paid although it should not have been (magenta)", fontsize=10)
    plt.tight_layout()
    show(plt.gcf())
